-- ---------------------------------------------------------------------------
-- MARKET (Neak Loeng Market) unit-rate lists
-- (from 03242023_BOQ of Neak Loeng Market (Updated 01).xlsx:
--  sheet 'PRELIMINARY WORK' -> Lump Sum Work list, sheet 'Market' -> Material/Labor rates)
-- Idempotent: each category is appended only if its category id is not already
-- present. Safe to re-run. Run in the Supabase SQL editor (or at the end of a
-- full supabase.sql re-run).
-- ---------------------------------------------------------------------------

-- Lump Sum Work list (third list): new category 'Market · Lump Sum Work' (mkls_1). jsonb_set creates the lumpSum key on ledgers that do not have it yet.
update public.ledger
set state = jsonb_set(
  state,
  '{lumpSum}',
  COALESCE(state->'lumpSum', '[]'::jsonb) || '{"children": [{"children": [], "id": "mkls_1_1", "name": "Tools, equipment for testing & survey", "price": 3000, "unit": "lot"}, {"children": [], "id": "mkls_1_2", "name": "Shop drawings submission", "price": 2400, "unit": "lot"}, {"children": [], "id": "mkls_1_3", "name": "Material samples submission and cost for testing, submission of testing certificate", "price": 2000, "unit": "lot"}, {"children": [], "id": "mkls_1_4", "name": "As-built drawings submission", "price": 800, "unit": "lot"}, {"children": [], "id": "mkls_1_5", "name": "Project manager/Construction manager", "price": 16800, "unit": "lot"}, {"children": [], "id": "mkls_1_6", "name": "Site manager", "price": 9600, "unit": "lot"}, {"children": [], "id": "mkls_1_7", "name": "Site engineer", "price": 10800, "unit": "lot"}, {"children": [], "id": "mkls_1_8", "name": "QA/QC, safety engineer", "price": 12000, "unit": "lot"}, {"children": [], "id": "mkls_1_9", "name": "Site Admins, and others", "price": 3600, "unit": "lot"}, {"children": [], "id": "mkls_1_10", "name": "Temporary Power consumption", "price": 3000, "unit": "lot"}, {"children": [], "id": "mkls_1_11", "name": "Temporary Water consumption", "price": 1500, "unit": "lot"}, {"children": [], "id": "mkls_1_12", "name": "Temporary Office and Storage", "price": 3750, "unit": "lot"}, {"children": [], "id": "mkls_1_13", "name": "Site daily cleaning include remove rubbish, debris, etc…", "price": 4500, "unit": "lot"}, {"children": [], "id": "mkls_1_14", "name": "PPE to be provided and renewed if damaged, including helmet, shoes, reflective vest, safety glasses for:", "price": 1500, "unit": "lot"}, {"children": [], "id": "mkls_1_15", "name": "Cost for provision of Workmen Compensation Insurance", "price": 3000, "unit": "lot"}], "id": "mkls_1", "name": "Market · Lump Sum Work", "price": 0, "unit": ""}'::jsonb,
  true
)
where id = 1
  and not exists (
    select 1 from jsonb_array_elements(COALESCE(state->'lumpSum', '[]'::jsonb)) c
    where c->>'id' = 'mkls_1'
  );

